from pathlib import Path

def resolve_merge(text: str) -> str:
    lines = text.splitlines(True)
    out, mode, buf_up, buf_st = [], "keep", [], []
    for line in lines:
        if line.startswith("<<<<<<<"):
            mode = "up"; buf_up, buf_st = [], []; continue
        if line.startswith("=======") and mode == "up":
            mode = "st"; continue
        if line.startswith(">>>>>>>"):
            seen=set()
            for chunk in (buf_up, buf_st):
                for L in chunk:
                    if L.strip() and L in seen: continue
                    seen.add(L); out.append(L)
            mode="keep"; continue
        if mode=="keep": out.append(line)
        elif mode=="up": buf_up.append(line)
        else: buf_st.append(line)
    assert mode=="keep"
    return "".join(out)

